@Data
public class ApplicantInfo
{
	private Role role;
	private Weapon weapon;
	private final List<String> recentMessages = new ArrayList<>();
	private final Map<KitType, Integer> equipment = new HashMap<>();

	public void addMessage(String msg)
	{
		if (recentMessages.size() >= 5)
		{
			recentMessages.remove(0);
		}
		recentMessages.add(msg);
	}
}

package com.tobrecruithelper;

public class ChatParser
{
	public static Role parseRole(String message)
	{
		String lower = message.toLowerCase();

		if (lower.contains("nfrz") || lower.contains("nf"))
		{
			return Role.NFRZ;
		}

		if (lower.contains("sfrz") || lower.contains("sf"))
		{
			return Role.SFRZ;
		}

		if (lower.contains("mdps"))
		{
			return Role.MDPS;
		}

		if (lower.contains("rdps"))
		{
			return Role.RDPS;
		}

		// Important: parse frz after nfrz/sfrz
		if (lower.contains("frz"))
		{
			return Role.FRZ;
		}

		return null;
	}

	public static Weapon parseWeapon(String message)
	{
		String lower = message.toLowerCase();

		if (lower.contains("scy"))
		{
			return Weapon.SCYTHE;
		}

		if (lower.matches(".*\\b(sra|soulreaper|soul-reaper)\\b.*"))
		{
			return Weapon.SOULREAPER_AXE;
		}

		return null;
	}

	public static String removeRoleLabel(String text)
	{
		return text.replaceAll("(?i) \\((Nfrz|Sfrz|Frz|Mdps|Rdps)\\)$", "");
	}

	public static String escapeHtml(String text)
	{
		return text
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;");
	}
}

package com.tobrecruithelper;

import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.IndexedSprite;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.ImageUtil;

public class IconUtil
{
	public static IndexedSprite buildWeaponSprite(ItemManager itemManager, Client client, int itemId, int width, int height, int offsetY)
	{
		BufferedImage rawImage = itemManager.getImage(itemId);
		if (rawImage == null)
		{
			return null;
		}

		BufferedImage cropped = cropTransparentPixels(rawImage);
		if (cropped == null)
		{
			return null;
		}

		BufferedImage resizedImage = ImageUtil.resizeImage(cropped, width, height);
		BufferedImage outlinedImage = addOutline(resizedImage);

		IndexedSprite sprite = ImageUtil.getImageIndexedSprite(outlinedImage, client);
		sprite.setOffsetY(offsetY);
		return sprite;
	}

	public static BufferedImage cropTransparentPixels(BufferedImage image)
	{
		int minX = image.getWidth();
		int minY = image.getHeight();
		int maxX = -1;
		int maxY = -1;

		for (int x = 0; x < image.getWidth(); x++)
		{
			for (int y = 0; y < image.getHeight(); y++)
			{
				if ((image.getRGB(x, y) >> 24) != 0)
				{
					minX = Math.min(minX, x);
					maxX = Math.max(maxX, x);
					minY = Math.min(minY, y);
					maxY = Math.max(maxY, y);
				}
			}
		}

		if (maxX < minX || maxY < minY)
		{
			return null;
		}

		return image.getSubimage(minX, minY, maxX - minX + 1, maxY - minY + 1);
	}

	public static BufferedImage addOutline(BufferedImage image)
	{
		int width = image.getWidth() + 2;
		int height = image.getHeight() + 2;

		BufferedImage result = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		BufferedImage silhouette = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);

		for (int x = 0; x < image.getWidth(); x++)
		{
			for (int y = 0; y < image.getHeight(); y++)
			{
				int argb = image.getRGB(x, y);
				int alpha = (argb >> 24) & 0xFF;
				if (alpha > 0)
				{
					silhouette.setRGB(x, y, (alpha << 24));
				}
			}
		}

		java.awt.Graphics2D g = result.createGraphics();
		int[] dx = {-1, 0, 1, -1, 1, -1, 0, 1};
		int[] dy = {-1, -1, -1, 0, 0, 1, 1, 1};
		for (int i = 0; i < 8; i++)
		{
			g.drawImage(silhouette, 1 + dx[i], 1 + dy[i], null);
		}

		g.drawImage(image, 1, 1, null);
		g.dispose();

		return result;
	}
}

package com.tobrecruithelper;

public enum Role
{
	NFRZ("Nfrz", "0096FF"),
	SFRZ("Sfrz", "0096FF"),
	FRZ("Frz", "0096FF"),
	MDPS("Mdps", "D22B2B"),
	RDPS("Rdps", "0BDA51");

	private final String label;
	private final String colorHex;

	Role(String label, String colorHex)
	{
		this.label = label;
		this.colorHex = colorHex;
	}

	public String getLabel() { return label; }
	public String getColorHex() { return colorHex; }
}

package com.tobrecruithelper;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.kit.KitType;

public class TestData
{
	public static Map<String, ApplicantInfo> createApplicants()
	{
		Map<String, ApplicantInfo> testApplicants = new HashMap<>();

		ApplicantInfo mdps = new ApplicantInfo();
		mdps.setRole(Role.MDPS);
		mdps.setWeapon(Weapon.SCYTHE);
		mdps.addMessage("scythe");
		mdps.addMessage("mdps");
		mdps.addMessage("This is a really long chat message that should wrap across multiple lines inside the applicant box so we can verify that the text stays within the available width.");
		mdps.getEquipment().put(KitType.WEAPON, ItemID.SCYTHE_OF_VITUR);

		ApplicantInfo rdps = new ApplicantInfo();
		rdps.setRole(Role.RDPS);
		rdps.setWeapon(Weapon.SOULREAPER_AXE);
		rdps.addMessage("sra");
		rdps.addMessage("rdps");
		rdps.getEquipment().put(KitType.WEAPON, ItemID.SOULREAPER);

		ApplicantInfo sfrz = new ApplicantInfo();
		sfrz.setRole(Role.NFRZ);
		sfrz.addMessage("nfrz");
		sfrz.addMessage("can freeze");

		testApplicants.put("TestMDPS", mdps);
		testApplicants.put("TestRDPS", rdps);
		testApplicants.put("TestSFRZ", sfrz);

		return testApplicants;
	}
}

